#!/usr/bin/env bash
# FishDev installer. Downloads one pinned FishDev release, verifies every download
# against SHA-256 digests recorded below, and writes into the project only after all
# checks pass. See docs/release-integrity.md.
set -euo pipefail

# BEGIN fishdev-release:installer-pins (generated by .config/ai/tools/release.py update; do not edit)
FISHDEV_RELEASE="v0.5.0"
FISHDEV_RELEASE_SOURCE="https://raw.githubusercontent.com/fishdan/fishdev/v0.5.0"
FISHDEV_FILES=(
    "start.ai f9cf8f94bf83ae558d5decbea4825ee331cc74722f281a16ae9fec4d41417c78"
    "fishdev-init.md 1203bf823ef1f03fb6aa3adbb14798dd7603520a232c30dfbb00bb2fc0ee3c0f"
    ".config/ai/defaults/constitution.md 3d95ca26524b2d281e553ced769a5a4c0dc710a81bb9bd4103942a3b9d940035"
    ".config/ai/defaults/verification.json acfcbd02dfd65dda1acf469b90201e6d6523d8a3aaf137bdcefa77510540dba3"
    ".config/ai/defaults/rules.json 7e6f2ce3182cea60a775e461f93ee4d103b68d8289d2f91cce7dd632789d2af6"
    ".config/ai/tools/fishdev.py 1f8e9016627a09a2485ebd05d78e17a7b8b3b98eeb9505c7054a0c8033f6cefa"
    "docs/verification-and-learning.md 5f134dc610987e9d48081af84f80b2ba2973e92f2985b4e6884162e6eb804394"
)
UV_VERSION="0.13.7"
UV_MINIMUM_VERSION="0.4.0"
UV_INSTALLER_URL="https://github.com/astral-sh/uv/releases/download/0.13.7/uv-installer.sh"
UV_INSTALLER_SHA256="d263ee68314cf5bea36b08e6bd9e2c4563240d7adb73756cf33af5c199b92db4"
SPECIFY_VERSION="1.3.3"
SPECIFY_WHEEL_URL="https://files.pythonhosted.org/packages/2d/89/404e8e9aa5518a6ebb72a2f70f847b282807feaf94074d576ab5f947596a/specify_cli-1.3.3-py3-none-any.whl"
SPECIFY_WHEEL_SHA256="661789638709a922bebb01cab2956c6be9730d487324ccdef9b4cb8ae8110c8b"
# END fishdev-release:installer-pins

FISHDEV_SOURCE="${FISHDEV_SOURCE:-$FISHDEV_RELEASE_SOURCE}"
STAGE=""
SHA256_TOOL=""

fail() {
    echo "FishDev install failed: $*" >&2
    exit 1
}

cleanup() {
    if [ -n "$STAGE" ]; then rm -rf "$STAGE"; fi
}

stage_dir() {
    if [ -z "$STAGE" ]; then
        STAGE="$(mktemp -d)" || fail "could not create a temporary directory"
        trap cleanup EXIT
    fi
}

select_sha256_tool() {
    if command -v sha256sum >/dev/null 2>&1; then
        SHA256_TOOL="sha256sum"
    elif command -v shasum >/dev/null 2>&1; then
        SHA256_TOOL="shasum"
    else
        fail "no SHA-256 tool found; install sha256sum (coreutils) or shasum (Perl) and rerun"
    fi
}

sha256_of() {
    local digest _
    if [ "$SHA256_TOOL" = "sha256sum" ]; then
        read -r digest _ < <(sha256sum "$1")
    else
        read -r digest _ < <(shasum -a 256 "$1")
    fi
    echo "$digest"
}

# fetch_verified URL DESTINATION EXPECTED_SHA256
fetch_verified() {
    local url="$1" destination="$2" expected="$3" actual
    [ -n "$SHA256_TOOL" ] || select_sha256_tool
    if ! curl --proto '=https,file' --proto-redir '=https' -fsSL "$url" -o "$destination"; then
        rm -f "$destination"
        fail "could not download $url"
    fi
    actual="$(sha256_of "$destination")"
    if [ "$actual" != "$expected" ]; then
        rm -f "$destination"
        fail "digest mismatch for $url (expected $expected, got $actual)"
    fi
}

# version_at_least FOUND MINIMUM: numeric dotted comparison, missing parts count as 0.
version_at_least() {
    local found="$1" minimum="$2" left right
    while [ -n "$found" ] || [ -n "$minimum" ]; do
        left="${found%%.*}"; right="${minimum%%.*}"
        left="${left:-0}"; right="${right:-0}"
        if [ "$left" -gt "$right" ]; then return 0; fi
        if [ "$left" -lt "$right" ]; then return 1; fi
        if [ "$found" = "${found#*.}" ]; then found=""; else found="${found#*.}"; fi
        if [ "$minimum" = "${minimum#*.}" ]; then minimum=""; else minimum="${minimum#*.}"; fi
    done
    return 0
}

preflight() {
    local existing
    for existing in start.ai .config/ai .specify; do
        if [ -e "$existing" ]; then
            fail "$existing already exists; this installer only sets up a project without FishDev or SpecKit"
        fi
    done
    command -v curl >/dev/null 2>&1 || fail "curl is required"
    select_sha256_tool
}

stage_fishdev() {
    local entry path digest
    stage_dir
    echo "Downloading and verifying FishDev $FISHDEV_RELEASE..."
    for entry in "${FISHDEV_FILES[@]}"; do
        path="${entry% *}"
        digest="${entry##* }"
        mkdir -p "$STAGE/fishdev/$(dirname "$path")"
        fetch_verified "$FISHDEV_SOURCE/$path" "$STAGE/fishdev/$path" "$digest"
    done
}

ensure_uv() {
    local found
    if command -v uv >/dev/null 2>&1; then
        found="$(uv --version | sed -n 's/^uv \([0-9][0-9.]*\).*/\1/p')"
        version_at_least "$found" "$UV_MINIMUM_VERSION" ||
            fail "uv $found is older than $UV_MINIMUM_VERSION; run 'uv self update $UV_VERSION' and rerun"
        echo "Using existing uv $found"
        return
    fi
    stage_dir
    echo "Installing uv $UV_VERSION..."
    fetch_verified "$UV_INSTALLER_URL" "$STAGE/uv-installer.sh" "$UV_INSTALLER_SHA256"
    sh "$STAGE/uv-installer.sh"
    export PATH="$HOME/.local/bin:$HOME/.cargo/bin:$PATH"
    command -v uv >/dev/null 2>&1 || fail "uv was installed but is not on PATH; open a new shell and rerun"
}

install_speckit() {
    local current wheel
    current="$(uv tool list 2>/dev/null | sed -n 's/^specify-cli v\([^ ]*\).*/\1/p')"
    if [ "$current" = "$SPECIFY_VERSION" ]; then
        echo "Using existing specify-cli $current"
        return
    fi
    if [ -n "$current" ]; then
        echo "Replacing specify-cli $current with pinned $SPECIFY_VERSION"
    else
        echo "Installing specify-cli $SPECIFY_VERSION..."
    fi
    stage_dir
    wheel="$STAGE/${SPECIFY_WHEEL_URL##*/}"
    fetch_verified "$SPECIFY_WHEEL_URL" "$wheel" "$SPECIFY_WHEEL_SHA256"
    uv tool install --force "$wheel"
}

write_fishdev() {
    local entry path ignored
    echo "Writing FishDev files..."
    for entry in "${FISHDEV_FILES[@]}"; do
        path="${entry% *}"
        mkdir -p "$(dirname "$path")"
        cp "$STAGE/fishdev/$path" "$path"
    done
    cp .config/ai/defaults/verification.json .config/ai/verification.json
    cp .config/ai/defaults/rules.json .config/ai/rules.json
    touch .gitignore
    for ignored in '.config/ai/reports/' '.config/ai/local/' '.config/ai/learning/proposals.json' '__pycache__/'; do
        grep -Fxq "$ignored" .gitignore || echo "$ignored" >> .gitignore
    done

    echo "Read and follow start.ai before doing any work." > AGENTS.md
    cp AGENTS.md CLAUDE.md
    cp AGENTS.md GEMINI.md
    echo "# Repository Settings" > .config/ai/repo.ai
    echo "# Progress Log" > .config/ai/progress.ai
    echo "# Handoff" > .config/ai/handoff.ai
}

init_speckit() {
    local specify
    echo "Initializing SpecKit..."
    specify="$(command -v specify || true)"
    if [ -z "$specify" ]; then specify="$(uv tool dir --bin)/specify"; fi
    # --ignore-agent-tools avoids interactive agent checks during automated setup.
    "$specify" init . --here --force --ignore-agent-tools --script sh --integration generic \
        --integration-options="--commands-dir .config/ai/commands"
    mkdir -p .specify/memory
    cp .config/ai/defaults/constitution.md .specify/memory/constitution.md
}

main() {
    echo "Initializing FishDev $FISHDEV_RELEASE..."
    preflight
    stage_fishdev
    ensure_uv
    install_speckit
    write_fishdev
    init_speckit
    echo ""
    echo "FishDev $FISHDEV_RELEASE bootstrap complete."
    echo ""
    echo "Next steps:"
    echo "Tell your AI assistant to follow the instructions in ./start.ai, and start every future session that way."
}

if [ "${FISHDEV_INSTALL_LIBRARY:-}" != "1" ]; then
    main "$@"
fi
